16	var errFaultInjectionUnsupported = errors.New("deterministic fault injection unsupported on this platform")
17	
18	func testEvent(id string, at time.Time) events.Event {
19		return events.Event{ID: id, Service: "svc", Severity: "info", Message: "msg-" + id, At: at}
20	}
21	
22	func TestAppendAndReopen(t *testing.T) {
23		dir := t.TempDir()
24		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
25	
26		log, batches, err := Open(dir)
27		if err != nil {
28			t.Fatalf("open: %v", err)
29		}
30		if err := log.Append([]events.Event{testEvent("a", base), testEvent("b", base.Add(time.Second))}); err != nil {
31			t.Fatalf("append: %v", err)
32		}
33		if err := log.Append([]events.Event{testEvent("c", base.Add(2*time.Second))}); err != nil {
34			t.Fatalf("append: %v", err)
35		}
36		if err := log.Close(); err != nil {
37			t.Fatalf("close: %v", err)
38		}
39	
40		log2, batches, err := Open(dir)
41		if err != nil {
42			t.Fatalf("reopen: %v", err)
43		}
44		defer log2.Close()
45		if len(batches) != 2 || len(batches[0]) != 2 || len(batches[1]) != 1 {
46			t.Fatalf("unexpected recovered batches: %+v", batches)
47		}
48		flat := []string{batches[0][0].ID, batches[0][1].ID, batches[1][0].ID}
49		if strings.Join(flat, ",") != "a,b,c" {
50			t.Fatalf("recovery order: %v", flat)
51		}
52		if !batches[0][0].At.Equal(base) {
53			t.Fatalf("timestamp not preserved absolutely: %v", batches[0][0].At)
54		}
55	
56		// A new batch after recovery appends cleanly and reads back as frame 3.
57		if err := log2.Append([]events.Event{testEvent("d", base.Add(3*time.Second))}); err != nil {
58			t.Fatalf("append after recovery: %v", err)
59		}
60		if err := log2.Close(); err != nil {
61			t.Fatalf("close: %v", err)
62		}
63		_, batches, err = Open(dir)
64		if err != nil {
65			t.Fatalf("reopen 2: %v", err)
66		}
67		if len(batches) != 3 || batches[2][0].ID != "d" {
68			t.Fatalf("post-tail-write corrupted recovery: %+v", batches)
69		}
70	}
71	
72	func TestReplayIgnoresTornTailOnly(t *testing.T) {
73		dir := t.TempDir()
74		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
75		path := filepath.Join(dir, logName)
76	
77		log, _, err := Open(dir)
78		if err != nil {
79			t.Fatalf("open: %v", err)
80		}
81		if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
82			t.Fatalf("append: %v", err)
83		}
84		if err := log.Append([]events.Event{testEvent("b", base.Add(time.Second))}); err != nil {
85			t.Fatalf("append: %v", err)
86		}
87		log.Close()
88	
89		good, err := os.ReadFile(path)
90		if err != nil {
91			t.Fatalf("read: %v", err)
92		}
93	
94		// Torn payload: full header promising more bytes than exist.
95		payload, _ := events.MarshalBatch([]events.Event{testEvent("torn", base.Add(2*time.Second))})
96		partialHeader := make([]byte, 5) // also exercises a short partial header
97		binary.BigEndian.PutUint32(partialHeader[0:4], uint32(len(payload)))
98	
99		cases := map[string][]byte{
100			"partial header":  partialHeader,
101			"partial payload": frameFor(payload)[:headerSize+3],
102			"full header only": func() []byte {
103				b := make([]byte, headerSize)
104				binary.BigEndian.PutUint32(b[0:4], uint32(len(payload)))
105				binary.BigEndian.PutUint32(b[4:8], crc32.ChecksumIEEE(payload))
106				return b
107			}(),
108		}
109		for name, tail := range cases {
110			t.Run(name, func(t *testing.T) {
111				if err := os.WriteFile(path, append(append([]byte(nil), good...), tail...), 0o644); err != nil {
112					t.Fatalf("seed torn file: %v", err)
113				}
114				log2, batches, err := Open(dir)
115				if err != nil {
116					t.Fatalf("torn tail must be tolerated: %v", err)
117				}
118				if len(batches) != 2 {
119					t.Fatalf("want 2 intact batches, got %d", len(batches))
120				}
121				// Ignored tail must not pollute the next write.
122				if err := log2.Append([]events.Event{testEvent("after", base.Add(3*time.Second))}); err != nil {
123					t.Fatalf("append over torn tail: %v", err)
124				}
125				log2.Close()
126	
127				log3, recovered, err := Open(dir)
128				if err != nil {
129					t.Fatalf("reopen: %v", err)
130				}
131				if len(recovered) != 3 || recovered[2][0].ID != "after" {
132					log3.Close()
133					t.Fatalf("tail leaked into later frames: %+v", recovered)
134				}
135				log3.Close()
136			})
137		}
138	}
139	
140	// frameFor wraps a payload the same way Log.Append does.
141	func frameFor(payload []byte) []byte {
142		frame := make([]byte, headerSize+len(payload))
143		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
144		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
145		copy(frame[headerSize:], payload)
146		return frame
147	}
148	
149	func TestReplayFailsOnMidCorruption(t *testing.T) {
150		dir := t.TempDir()
151		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
152		path := filepath.Join(dir, logName)
153	
154		log, _, err := Open(dir)
155		if err != nil {
156			t.Fatalf("open: %v", err)
157		}
158		if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
159			t.Fatalf("append: %v", err)
160		}
161		log.Close()
162	
163		original, err := os.ReadFile(path)
164		if err != nil {
165			t.Fatalf("read: %v", err)
166		}
167		firstFrameLen := headerSize + int(binary.BigEndian.Uint32(original[0:4]))
168	
169		// A complete-looking second frame with a bad checksum.
170		payload, _ := events.MarshalBatch([]events.Event{testEvent("x", base.Add(time.Second))})
171		bad := frameFor(payload)
172		bad[headerSize] ^= 0xFF
173		corrupt := append(append([]byte(nil), original[:firstFrameLen]...), bad...)
174		if err := os.WriteFile(path, corrupt, 0o644); err != nil {
175			t.Fatalf("write: %v", err)
176		}
177	
178		if _, _, err := Open(dir); !isCorruption(err) {
179			t.Fatalf("mid corruption must fail startup, got %v", err)
180		}
181		if after, _ := os.ReadFile(path); string(after) != string(corrupt) {
182			t.Fatal("failed startup must not modify the data file")
183		}
184	}
185	
186	func isCorruption(err error) bool {
187		var target *CorruptionError
188		return errors.As(err, &target)
189	}
190	
191	func TestReplayFailsOnCompleteIllegalFrame(t *testing.T) {
192		dir := t.TempDir()
193		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
194		path := filepath.Join(dir, logName)
195	
196		log, _, err := Open(dir)
197		if err != nil {
198			t.Fatalf("open: %v", err)
199		}
200		if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
201			t.Fatalf("append: %v", err)
202		}
203		log.Close()
204	
205		original, _ := os.ReadFile(path)
206		firstFrameLen := headerSize + int(binary.BigEndian.Uint32(original[0:4]))
207	
208		// Complete frame with valid checksum carrying an unknown field.
209		illegal := []byte(`[{"id":"z","service":"s","severity":"info","message":"m","at":"2026-10-01T09:00:01Z","bogus":true}]`)
210		withIllegal := append(append([]byte(nil), original[:firstFrameLen]...), frameFor(illegal)...)
211		if err := os.WriteFile(path, withIllegal, 0o644); err != nil {
212			t.Fatalf("write: %v", err)
213		}
214		// A complete frame containing an empty batch is also illegal.
215		withEmpty := append(append([]byte(nil), original[:firstFrameLen]...), frameFor([]byte("[]"))...)
216		if err := os.WriteFile(path, withEmpty, 0o644); err != nil {
217			t.Fatalf("write empty frame: %v", err)
218		}
219		if _, _, err := Open(dir); !isCorruption(err) {
220			t.Fatalf("empty frame must fail startup, got %v", err)
221		}
222	}
223	
224	func TestAppendFailurePoisonsLog(t *testing.T) {
225		dir := t.TempDir()
226		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
227	
228		log, _, err := Open(dir)
229		if err != nil {
230			t.Fatalf("open: %v", err)
231		}
232		if err := log.Append([]events.Event{testEvent("a", base)}); err != nil {
233			t.Fatalf("append: %v", err)
234		}
235		if err := breakWriter(log); err != nil {
236			if errors.Is(err, errFaultInjectionUnsupported) {
237				t.Skip("deterministic write fault injection requires /dev/full")
238			}
239			t.Fatalf("inject fault: %v", err)
240		}
241	
242		err = log.Append([]events.Event{testEvent("b", base.Add(time.Second))})
243		if err == nil {
244			t.Fatal("write failure must return an error")
245		}
246		if !log.Poisoned() {
247			t.Fatalf("log must be poisoned after write error")
248		}
249		for range 3 {
250			if err := log.Append([]events.Event{testEvent("c", base.Add(2*time.Second))}); !errors.Is(err, ErrPoisoned) {
251				t.Fatalf("later writes must return ErrPoisoned, got %v", err)
252			}
253		}
254	}
255	
