// middle, or a complete frame the decoder rejects, is fatal and leaves the
// file untouched. The data directory is fsynced only when a torn tail was
// actually trimmed; callers that need an unconditional directory sync do so
// themselves. On success the returned frameLog is open for appends; on
// failure the file is already closed.
func openFrameFile(dir, name string, spec frameSpec, decode frameDecoder) (*frameLog, error) {
	if dir == "" {
		return nil, fmt.Errorf("data directory is required")
	}
	path := filepath.Join(dir, name)
	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open %s: %w", spec.noun, err)
	}
	ok := false
	defer func() {
		if !ok {
			file.Close()
		}
	}()

	data, err := os.ReadFile(file.Name())
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", spec.noun, err)
	}
	validLen, err := scanFrames(data, spec, decode)
	if err != nil {
		return nil, err
	}
	if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
		// Drop exactly one incomplete trailing frame. This is the only
		// mutation recovery performs, so it and its directory entry are
		// fsynced before serving.
		if err := file.Truncate(validLen); err != nil {
			return nil, fmt.Errorf("truncate incomplete trailing %sframe: %w", spec.word, err)
		}
		if err := file.Sync(); err != nil {
			return nil, fmt.Errorf("sync %s: %w", spec.noun, err)
		}
		if err := syncDir(dir); err != nil {
			return nil, fmt.Errorf("sync data directory: %w", err)
		}
	}

	ok = true
	return &frameLog{file: file}, nil
}

