 39	// timeline.
 40	func Open(dir string) (*Log, [][]events.Event, error) {
 41		if dir == "" {
 42			return nil, nil, errors.New("data directory is required")
 43		}
 44		if err := os.MkdirAll(dir, 0o755); err != nil {
 45			return nil, nil, fmt.Errorf("create data directory: %w", err)
 46		}
