 50		if err != nil {
 51			return nil, nil, fmt.Errorf("open directory lock: %w", err)
 52		}
 53		if err := tryLock(lockFile); err != nil {
 54			lockFile.Close()
 55			if errors.Is(err, errLocked) {
 56				return nil, nil, fmt.Errorf("data directory %q is in use by another signalroom instance", dir)
 57			}
 58			return nil, nil, fmt.Errorf("acquire directory lock: %w", err)
 59		}
 60	
 61		var batches [][]events.Event
 62		decode := func(payload []byte, offset int64) error {
 63			batch, err := events.DecodeBatch(payload)
 64			if err != nil {
 65				return corruption("illegal frame payload at offset %d: %v", offset, err)
 66			}
 67			if len(batch) == 0 {
 68				return corruption("empty batch frame at offset %d", offset)
 69			}
 70			for i := range batch {
 71				normalized, err := events.Normalize(batch[i])
 72				if err != nil {
 73					return corruption("invalid event in frame at offset %d: %v", offset, err)
 74				}
 75				batch[i] = normalized
 76			}
 77			batches = append(batches, batch)
 78			return nil
 79		}
